    <script>
        function createParticles() {
            const body = document.body;
            for (let i = 0; i < 8; i++) {
                const particle = document.createElement('div');
                particle.className = 'ambient-particle';
                particle.style.left = Math.random() * 100 + '%';
                particle.style.animationDelay = Math.random() * 15 + 's';
                particle.style.animationDuration = (12 + Math.random() * 8) + 's';
                body.appendChild(particle);
            }
        }

        function enhanceCandleFlicker() {
            const glow = document.querySelector('.candle-glow');
            if (glow) {
                setInterval(() => {
                    const randomOpacity = 0.7 + Math.random() * 0.3;
                    const randomScale = 0.95 + Math.random() * 0.1;
                    glow.style.opacity = randomOpacity;
                    glow.style.transform = `scale(${randomScale})`;
