        .flip-card-back::after {
            content: '"';
            font-family: Georgia, serif;
            font-size: 2rem;
            color: rgba(139, 69, 87, 0.15);
            position: absolute;
        }

        .flip-card-back::before {
            top: 12px;
            left: 15px;
        }

        .flip-card-back::after {
            content: '"';
            bottom: 12px;
            right: 15px;
