<!-- 结果弹窗 -->
<div id="resultModal">
    <div class="modal-content">
        <h3 style="text-align: center; border: none; margin-bottom: 10px;">角色档案已成</h3>
        <p style="text-align: center; color: #666; font-size: 0.9em; margin-top: 0;">请复制下方内容，发送给AI开启故事。</p>
        <div class="result-text" id="finalOutput"></div>
        <div class="modal-buttons">
            <button class="btn-copy" onclick="copyToClipboard()">复制内容</button>
            <button class="btn-close" onclick="closeModal()">关闭窗口</button>
        </div>
    </div>
</div>

<script>
    // 1. 处理“其他”选项的输入框显示/隐藏
    function toggleInput(selectId, inputId, triggerValue) {
        const select = document.getElementById(selectId);
        const input = document.getElementById(inputId);
        if(select.value === triggerValue || (selectId === 'origin' && select.value === 'other')) {
            input.style.display = 'block';
            input.focus();
        } else {
            input.style.display = 'none';
        }
    }

    // 2. 限制多选框数量
    const maxSkills = 3;
    const skillCheckboxes = document.querySelectorAll('input[name="skills"]');

    skillCheckboxes.forEach(checkbox => {
        checkbox.addEventListener('change', function() {
            const checkedCount = document.querySelectorAll('input[name="skills"]:checked').length;
            if (checkedCount > maxSkills) {
                this.checked = false; 
                alert("贪多嚼不烂，特长最多只能选择 " + maxSkills + " 项哦。");
            }
        });
    });

    // 辅助函数
    function getCheckedValues(name) {
        const checkboxes = document.querySelectorAll(`input[name="${name}"]:checked`);
        let values = [];
        checkboxes.forEach((checkbox) => {
            values.push(checkbox.value);
        });
        return values.length > 0 ? values.join("、") : "未选择";
    }

    function getRadioValue(name) {
        const radio = document.querySelector(`input[name="${name}"]:checked`);
        return radio ? radio.value : "未选择";
    }

    // 生成档案
    function generateProfile() {
        const name = document.getElementById('name').value || "未命名";
        const gender = getRadioValue('gender');
        const age = document.getElementById('age').value || "未知";
        const appearance = document.getElementById('appearance').value || "暂无描述";

        let origin = document.getElementById('origin').value || "未选";
        const originDetail = document.getElementById('originDetail').value;
        if(origin === 'other' || document.getElementById('originDetail').style.display === 'block') {
            if(originDetail) origin = origin === 'other' ? originDetail : origin + "：" + originDetail;
        }

        const position = document.getElementById('position').value || "无";

        let relation = document.getElementById('relation').value || "未选";
        const relationDetail = document.getElementById('relationDetail').value;
        if(relation === '其他' && relationDetail) relation = relationDetail;

        const background = document.getElementById('background').value || "暂无";

        const personalityCore = getCheckedValues('personality');
        const pros = document.getElementById('pros').value || "暂无";
        const cons = document.getElementById('cons').value || "暂无";
        const habits = document.getElementById('habits').value || "无";

        const skills = getCheckedValues('skills');
        const weakness = document.getElementById('weakness').value || "无";

        const hookReason = document.getElementById('hookReason').value || "命运安排";
        const attitude = getRadioValue('attitude');
        const secret = document.getElementById('secret').value || "无";

        const tone = document.getElementById('tone').value;
        const scale = document.getElementById('scale').value;
        const preferences = document.getElementById('preferences').value || "无特殊要求";

        const finalPrompt = `【${name} · 角色档案】

◈ 基础信息
- 姓名：${name}
- 性别：${gender}
- 年龄：${age}岁
- 外貌：${appearance}

◈ 身份背景
- 出身：${origin}
- 当前身份：${position}
- 与殷枕崖的关系：${relation}
- 背景简述：${background}

◈ 性格特质
- 核心性格：${personalityCore}
- 优点：${pros}
- 缺点：${cons}
- 特殊习惯：${habits}

◈ 能力特长
- 擅长：${skills}
- 弱项：${weakness}

◈ 故事设定
- 交集缘由：${hookReason}
- 初始态度：${attitude}
- 隐藏秘密：${secret}

◈ 剧情偏好
- 基调：${tone}
- 尺度：${scale}
- 特殊要求：${preferences}

【请根据以上信息，生成符合大燕王朝风格的开场剧情，请注意文风古韵。】`;

        document.getElementById('finalOutput').textContent = finalPrompt;
        document.getElementById('resultModal').style.display = 'flex';
    }

    function closeModal() {
        document.getElementById('resultModal').style.display = 'none';
    }

    function copyToClipboard() {
        const text = document.getElementById('finalOutput').textContent;
        navigator.clipboard.writeText(text).then(() => {
            alert('复制成功，快去开启你的长安之旅吧！');
        }).catch(err => {
            const textArea = document.createElement("textarea");
            textArea.value = text;
            document.body.appendChild(textArea);
            textArea.select();
            document.execCommand("Copy");
            textArea.remove();
            alert('复制成功！');
        });
    }
</script>

</body>
</html>
